//! Embedded skill and preset files generated by build.rs.

include!(concat!(env!("OUT_DIR"), "/embedded_data.rs"));

pub fn lookup(
    table: &'static [(&'static str, &'static [u8])],
    path: &str,
) -> Option<&'static [u8]> {
    table
        .iter()
        .find(|(entry, _)| *entry == path)
        .map(|(_, bytes)| *bytes)
}
